417	/// The kind of block a top-level statement makes, or `None` when it is not one.
418	fn statement_kind(statement: &Statement<'_>) -> Option<SymbolKind> {
419	    match statement {
420	        Statement::FunctionDeclaration(_) => Some(SymbolKind::Function),
421	        Statement::ClassDeclaration(_) => Some(SymbolKind::Class),
422	        Statement::TSInterfaceDeclaration(_) => Some(SymbolKind::Interface),
423	        Statement::TSTypeAliasDeclaration(_) => Some(SymbolKind::TypeAlias),
424	        Statement::TSEnumDeclaration(_) => Some(SymbolKind::Enum),
425	        Statement::VariableDeclaration(_) => Some(SymbolKind::Variable),
426	        Statement::ExportDeclaration(export) => {
427	            Some(declaration_kind(&export.declaration).unwrap_or(SymbolKind::Other))
428	        }
429	        Statement::ImportDeclaration(_)
430	        | Statement::ExportNamedDeclaration(_)
431	        | Statement::ExportFromDeclaration(_)
432	        | Statement::ExportDefaultDeclaration(_)
433	        | Statement::ExportAllDeclaration(_) => Some(SymbolKind::Other),
434	        _ => None,
435	    }
436	}
437	
438	fn declaration_kind(decl: &Declaration<'_>) -> Option<SymbolKind> {
439	    match decl {
440	        Declaration::FunctionDeclaration(_) => Some(SymbolKind::Function),
441	        Declaration::ClassDeclaration(_) => Some(SymbolKind::Class),
442	        Declaration::TSInterfaceDeclaration(_) => Some(SymbolKind::Interface),
443	        Declaration::TSTypeAliasDeclaration(_) => Some(SymbolKind::TypeAlias),
444	        Declaration::TSEnumDeclaration(_) => Some(SymbolKind::Enum),
445	        Declaration::VariableDeclaration(_) => Some(SymbolKind::Variable),
446	        Declaration::TSExternalModuleDeclaration(_)
447	        | Declaration::TSNamespaceDeclaration(_)
448	        | Declaration::TSGlobalDeclaration(_)
449	        | Declaration::TSImportEqualsDeclaration(_) => None,
450	    }
451	}
452	
453	/// The function a statement declares, directly or through `export`.
454	fn statement_function<'a, 'b>(statement: &'b Statement<'a>) -> Option<&'b Function<'a>> {
455	    match statement {
456	        Statement::FunctionDeclaration(function) => Some(function),
457	        Statement::ExportDeclaration(export) => match &export.declaration {
458	            Declaration::FunctionDeclaration(function) => Some(function),
459	            _ => None,
460	        },
461	        _ => None,
462	    }
463	}
464	
465	fn module_export_name(name: &ModuleExportName<'_>) -> String {
466	    match name {
467	        ModuleExportName::IdentifierName(id) => id.name.as_str().to_owned(),
468	        ModuleExportName::IdentifierReference(id) => id.name.as_str().to_owned(),
469	        ModuleExportName::StringLiteral(literal) => literal.value.as_str().to_owned(),
470	    }
471	}
472	
473	/// Collects every JSX element in document order.
474	struct JsxCollector<'l> {
475	    lines: &'l LineIndex,
476	    found: Vec<JsxElementEntry>,
477	}
478	
479	impl<'a> Visit<'a> for JsxCollector<'_> {
480	    fn visit_jsx_element(&mut self, element: &JSXElement<'a>) {
481	        let opening = &element.opening_element;
482	        let name = jsx_element_name(&opening.name);
483	        let attributes = opening.attributes.iter().map(jsx_attribute).collect();
484	        self.found.push(JsxElementEntry {
485	            is_html: name.chars().next().is_some_and(char::is_lowercase),
486	            name,
487	            line: self.lines.line(opening.span.start),
488	            attributes,
489	        });
490	        walk::walk_jsx_element(self, element);
491	    }
492	}
493	
494	fn jsx_attribute(item: &JSXAttributeItem<'_>) -> JsxAttribute {
495	    match item {
496	        JSXAttributeItem::Attribute(attribute) => {
497	            let name = match &attribute.name {
498	                JSXAttributeName::Identifier(id) => id.name.as_str().to_owned(),
499	                JSXAttributeName::NamespacedName(ns) => format!("{}:{}", ns.namespace.name, ns.name.name),
500	            };
501	            let (string_value, is_expression) = match &attribute.value {
502	                Some(JSXAttributeValue::StringLiteral(literal)) => (Some(literal.value.as_str().to_owned()), false),
503	                Some(
504	                    JSXAttributeValue::ExpressionContainer(_)
505	                    | JSXAttributeValue::Element(_)
506	                    | JSXAttributeValue::Fragment(_),
507	                ) => (None, true),
508	                None => (None, false),
509	            };
510	            JsxAttribute { name, string_value, is_expression, is_spread: false }
511	        }
512	        JSXAttributeItem::SpreadAttribute(_) => {
513	            JsxAttribute { name: "...".to_owned(), string_value: None, is_expression: false, is_spread: true }
514	        }
515	    }
516	}
517	
518	fn jsx_element_name(name: &JSXElementName<'_>) -> String {
519	    match name {
520	        JSXElementName::Identifier(id) => id.name.as_str().to_owned(),
521	        JSXElementName::IdentifierReference(id) => id.name.as_str().to_owned(),
522	        JSXElementName::NamespacedName(ns) => format!("{}:{}", ns.namespace.name, ns.name.name),
523	        JSXElementName::MemberExpression(member) => jsx_member(member),
524	        JSXElementName::ThisExpression(_) => "this".to_owned(),
525	    }
526	}
527	
528	fn jsx_member(member: &JSXMemberExpression<'_>) -> String {
529	    let object = match &member.object {
530	        JSXMemberExpressionObject::IdentifierReference(id) => id.name.as_str().to_owned(),
531	        JSXMemberExpressionObject::MemberExpression(inner) => jsx_member(inner),
532	        JSXMemberExpressionObject::ThisExpression(_) => "this".to_owned(),
533	    };
534	    format!("{object}.{}", member.property.name)
535	}
