473	/// Collects every JSX element in document order.
474	struct JsxCollector<'l> {
475	    lines: &'l LineIndex,
476	    found: Vec<JsxElementEntry>,
477	}
478	
479	impl<'a> Visit<'a> for JsxCollector<'_> {
480	    fn visit_jsx_element(&mut self, element: &JSXElement<'a>) {
481	        let opening = &element.opening_element;
482	        let name = jsx_element_name(&opening.name);
483	        let attributes = opening.attributes.iter().map(jsx_attribute).collect();
484	        self.found.push(JsxElementEntry {
485	            is_html: name.chars().next().is_some_and(char::is_lowercase),
486	            name,
487	            line: self.lines.line(opening.span.start),
488	            attributes,
489	        });
490	        walk::walk_jsx_element(self, element);
491	    }
492	}
493	
494	fn jsx_attribute(item: &JSXAttributeItem<'_>) -> JsxAttribute {
495	    match item {
496	        JSXAttributeItem::Attribute(attribute) => {
497	            let name = match &attribute.name {
498	                JSXAttributeName::Identifier(id) => id.name.as_str().to_owned(),
499	                JSXAttributeName::NamespacedName(ns) => format!("{}:{}", ns.namespace.name, ns.name.name),
500	            };
501	            let (string_value, is_expression) = match &attribute.value {
502	                Some(JSXAttributeValue::StringLiteral(literal)) => (Some(literal.value.as_str().to_owned()), false),
503	                Some(
504	                    JSXAttributeValue::ExpressionContainer(_)
505	                    | JSXAttributeValue::Element(_)
506	                    | JSXAttributeValue::Fragment(_),
507	                ) => (None, true),
508	                None => (None, false),
509	            };
510	            JsxAttribute { name, string_value, is_expression, is_spread: false }
511	        }
512	        JSXAttributeItem::SpreadAttribute(_) => {
513	            JsxAttribute { name: "...".to_owned(), string_value: None, is_expression: false, is_spread: true }
514	        }
515	    }
516	}
517	
518	fn jsx_element_name(name: &JSXElementName<'_>) -> String {
519	    match name {
520	        JSXElementName::Identifier(id) => id.name.as_str().to_owned(),
521	        JSXElementName::IdentifierReference(id) => id.name.as_str().to_owned(),
522	        JSXElementName::NamespacedName(ns) => format!("{}:{}", ns.namespace.name, ns.name.name),
523	        JSXElementName::MemberExpression(member) => jsx_member(member),
524	        JSXElementName::ThisExpression(_) => "this".to_owned(),
525	    }
526	}
527	
528	fn jsx_member(member: &JSXMemberExpression<'_>) -> String {
529	    let object = match &member.object {
530	        JSXMemberExpressionObject::IdentifierReference(id) => id.name.as_str().to_owned(),
531	        JSXMemberExpressionObject::MemberExpression(inner) => jsx_member(inner),
532	        JSXMemberExpressionObject::ThisExpression(_) => "this".to_owned(),
533	    };
534	    format!("{object}.{}", member.property.name)
535	}
